import time
import mujoco
from scipy.spatial.transform import Rotation as Rot
import numpy as np
from PIL import Image

def pos(name):
    return s.data.xpos[s.model.body(name).id].copy()
def site(arm='right'):
    i=s.model.site('gripper0_'+arm+'_grip_site').id
    return s.data.site_xpos[i].copy(),s.data.site_xmat[i].reshape(3,3).copy()
def info():
    print('step',len(s.actions),'obj',pos('obj_main').round(4),'pan',pos('container_main').round(4),'hand',site()[0].round(4),'check',s.check(),flush=True)
def render(name='now'):
    Image.fromarray(s.render('egoview',size=(640,480))).save('/app/output/'+name+'.png')
def move(p=None,H=None,grip=None,n=50,arm='right',hold=10):
    a=s.targets.copy(); k=0 if arm=='right' else 6; g=12 if arm=='right' else 18
    b=s.model.body('robot0_base').id; R=s.data.xmat[b].reshape(3,3).copy(); t=s.data.xpos[b].copy()
    if p is not None:a[k:k+3]=R.T@(np.array(p)-t)
    if H is not None:a[k+3:k+6]=Rot.from_matrix(R.T@H).as_rotvec()
    if grip is not None:a[g:g+6]=grip
    start=s.targets.copy()
    for f in np.linspace(0,1,n):s.step(start*(1-f)+a*f)
    for _ in range(hold):s.step(a)
    info()
def contacts():
    pairs=[]
    for c in s.data.contact:
        a=s.model.geom(c.geom1).name;b=s.model.geom(c.geom2).name
        if a.startswith('obj_') or b.startswith('obj_'):pairs.append((a,b,round(c.dist,4)))
    print(pairs)
Hdown=np.diag([1.,-1.,-1.])
